     2	import domain.MemberStatement;
     3	import domain.RunResult;
     4	
     5	import java.time.LocalDate;
     6	import java.time.YearMonth;
     7	import java.util.ArrayList;
     8	import java.util.LinkedHashMap;
     9	import java.util.List;
    10	import java.util.Map;
    11	
    12	/** End-to-end: the 10/06 acquirer export through the nightly earn run, then what members see. */
    13	public class PointsE2ETest {
    14	    private static final LocalDate DAY = LocalDate.of(2026, 10, 6);
    15	    private static final YearMonth OCT = YearMonth.of(2026, 10);
    16	
    17	    public static void main(String[] args) throws Exception {
    18	        TestSupport t = new TestSupport("e2e");
    19	        PointsApi api = new PointsApi(TestSupport.sandbox());
    20	        RunResult run = api.runDay(DAY);
    21	
    22	        t.test("10/06 run earns every approved payment of a known member once", () -> {
    23	            TestSupport.eq(10, run.earned(), "earned payments");
    24	            TestSupport.eq(List.of("999999"), run.unknownMembers(), "unknown members");
    25	        });
    26	
    27	        t.test("김서연 (store card 004512) sees the 2,068P she earned", () ->
    28	                TestSupport.eq(2_068L, api.statement("004512", OCT).balance(), "balance of 004512"));
    29	
    30	        t.test("박지훈 (app 4512) sees only his own 690P", () ->
    31	                TestSupport.eq(690L, api.statement("4512", OCT).balance(), "balance of 4512"));
    32	
    33	        t.test("every member's balance equals the points earned from their own payments", () -> {
    34	            Map<String, Long> expected = new LinkedHashMap<>();
    35	            expected.put("4512", 690L);
    36	            expected.put("004512", 2_068L);
